import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import text from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets - Asset URLs.
 * @property {string} assets.imageUrl - URL of the plane texture.
 * @property {Array<number>} [position] - [x, y, z] world position.
 * @property {Array<number>} [rotation] - [x, y, z] Euler rotation (radians).
 * @property {Array<number>} [scale] - [x, y, z] scale.
 * @property {Array<Object>} [cinematicPrimitives] - Primitives to apply.
 */

/**
 * @typedef {Object} NodeContext
 * @property {{load: (url:string)=>THREE.Texture}} textureLoader
 * @property {Object.<string, Function>} primitives - Primitive functions.
 * @property {any} fontAtlas
 */

/**
 * Creates a textured plane node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// ----- Geometry -------------------------------------------------
	const texture = ctx.textureLoader.load(config.assets.imageUrl);
	const aspect = texture.image?.width && texture.image?.height
		? texture.image.width / texture.image.height
		: 1; // fallback square

	const geometry = new THREE.PlaneGeometry(aspect, 1, 1, 1);

	// ----- Material -------------------------------------------------
	const material = new THREE.MeshBasicNodeMaterial();
	material.transparent = true;
	material.colorNode = texture(texture);
	// ensure texture mapping uses correct encoding
	if (texture) {
		texture.encoding = THREE.sRGBEncoding;
		texture.needsUpdate = true;
	}

	// ----- Mesh -----------------------------------------------------
	const mesh = new THREE.Mesh(geometry, material);
	mesh.name = config.name ?? 'PrimaryCTA';

	// ----- Placement ------------------------------------------------
	const pos = config.position ?? config.scenePlacement?.position ?? [0, 0, 0];
	const rot = config.rotation ?? config.scenePlacement?.rotation ?? [0, 0, 0];
	const scl = config.scale ?? config.scenePlacement?.scale ?? [1, 1, 1];

	mesh.position.set(pos[0] ?? 0, pos[1] ?? 0, pos[2] ?? 0);
	mesh.rotation.set(rot[0] ?? 0, rot[1] ?? 0, rot[2] ?? 0);
	mesh.scale.set(scl[0] ?? 1, scl[1] ?? 1, scl[2] ?? 1);

	// ----- Cinematic Primitives --------------------------------------
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const primitive of config.cinematicPrimitives) {
			const fn = ctx.primitives[primitive.name];
			if (typeof fn === 'function') {
				fn(mesh, primitive.params);
			}
		}
	}

	// ----- UserData & Cleanup ----------------------------------------
	const timelines = [];

	mesh.userData.handlers = {};

	mesh.userData.cleanup = () => {
		// dispose three.js resources
		geometry.dispose();
		material.dispose();
		if (texture) texture.dispose();

		// kill any GSAP timelines created by this node
		for (const tl of timelines) {
			if (tl && tl.kill) tl.kill();
		}
		timelines.length = 0;
	};

	// ----- Return ---------------------------------------------------
	return mesh;
}
